const lead = $('Normalize Lead Data').first().json;
let ai;
try {
  const raw = $input.first().json.choices[0].message.content;
  const cleaned = raw.replace(/```json|```/g, '').trim();
  ai = JSON.parse(cleaned);
} catch (e) {
  ai = { intent: 'unknown', buying_stage: 'unknown', pain_points: '', urgency: 'low', estimated_value: 0, lead_score: 20, recommended_action: 'manual_review', recommended_channel: 'email' };
}
const score = Math.max(0, Math.min(100, Number(ai.lead_score) || 0));
let tier = 'cold';
if (score >= 85) tier = 'high_priority';
else if (score >= 70) tier = 'hot';
else if (score >= 40) tier = 'warm';
return [{ json: { ...lead, ...ai, lead_score: score, tier, status: 'new', follow_up_count: 0, next_followup_at: '' } }];

