let ai;
try {
  const raw = $input.first().json.choices[0].message.content;
  ai = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch (e) {
  ai = { reply_intent: 'question', objection_topic: '', summary: 'could not parse, needs human review' };
}
const lead = $('Get Lead By ID').first().json;
const reply = $('Normalize Reply Data').first().json;
return [{ json: { ...lead, ...reply, ...ai } }];

// Search Config sheet FAQ rows (already fetched into $json.faq_rows upstream in real build)
const topic = ($json.objection_topic || '').toLowerCase();
const faqs = $json.faq_rows || [];
const match = faqs.find(f => topic && f.topic && f.topic.toLowerCase() === topic);
return [{ json: { ...$json, faq_match: match ? match.answer : null } }];

const MAX_FOLLOWUPS = 4;
const hour = new Date().getHours();
const withinBusinessHours = hour >= 9 && hour < 19; // Asia/Karachi business hours
const withinCap = Number($json.follow_up_count || 0) < MAX_FOLLOWUPS;
return [{ json: { ...$json, can_send: withinBusinessHours && withinCap } }];
